const express = require('express');
const Pool = require('pg-pool');

const app = express();

const tenantVaultPools = new Map();

function getVaultPool(orgUuid) {
  if (!tenantVaultPools.has(orgUuid)) {
    tenantVaultPools.set(
      orgUuid,
      new Pool({
        connectionString: `postgresql://vault_user:${process.env.VAULT_PASS}@pg-vault.internal:5432/vault_${orgUuid}`
      })
    );
  }
  return tenantVaultPools.get(orgUuid);
}

app.get('/api/vault/documents/index', async (req, res) => {
  if (!req.user || !req.user.organizationUuid) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const requestedOrgUuid = req.headers['x-organization-uuid'];

  // Verify that caller belongs to the organization whose database pool is being queried
  if (requestedOrgUuid && requestedOrgUuid !== req.user.organizationUuid) {
    return res.status(403).json({ error: 'Access denied: cannot query document vault of another organization' });
  }

  const activeOrgUuid = req.user.organizationUuid;
  const pool = getVaultPool(activeOrgUuid);

  try {
    const { rows } = await pool.query(
      'SELECT doc_id, title, classification, file_hash, uploaded_by, created_at FROM document_index LIMIT 100'
    );
    res.json({ organization: activeOrgUuid, documents: rows });
  } catch (err) {
    res.status(500).json({ error: 'Failed to query document vault' });
  }
});

app.listen(9108);
